def lg_designation(p1, p2, il):
    """§3.2.4.1:各片最小厚度之和 + 中間膜(合計上限 1.52 mm),取 Table 4 中最小厚度不大於該值之最大代號,並套用例外。"""
    ssum = DESIG_T[p1] + DESIG_T[p2] + min(il, 1.52)
    if p1 == p2 == 6.0 and (abs(il - 0.38) <= 0.02 or abs(il - 0.76) <= 0.02):   # 例外僅適用指定 0.38 / 0.76 mm 中間膜
        return 12.0
    if p1 == p2 == 2.5 and il >= 1.52 - 1e-9:
        return 5.0
    if p1 == p2 == 4.0:
        return 8.0
    return max(d for d, m in DESIG_T.items() if m <= ssum + 1e-9)

