_FONT = "font-family:'Microsoft JhengHei','PingFang TC',sans-serif"


def _svg_frame(w, h, ml, mr, mt, mb):
    return w, h, ml, mr, mt, mb


def svg_nfl4(item, ck, L, S, title):
    """四邊簡支 NFL 圖(依數位化等值線重繪):x = 長邊、y = 短邊,紅線標示 (L, S) 讀值點。"""
    ch = load4()[ck]
    xm, ym = float(X4_MAX[ck]), float(S4_MAX[ck])
    W, H, ml, mr, mt, mb = 560, 410, 56, 18, 34, 56
    pw, ph = W - ml - mr, H - mt - mb
    X = lambda x: ml + x / xm * pw
    Y = lambda y: mt + ph - y / ym * ph
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="100%" style="{_FONT};background:#fff">']
    o.append(f'<text x="{W/2}" y="18" text-anchor="middle" font-size="13" font-weight="bold">{_html.escape(title)}</text>')
    # 格線
    xs = int(np.ceil(xm / 500)); ys = int(np.ceil(ym / 500))
    for i in range(0, int(xm // 500) + 1):
        x = i * 500
        o.append(f'<line x1="{X(x):.1f}" y1="{Y(0):.1f}" x2="{X(x):.1f}" y2="{Y(ym):.1f}" stroke="#ddd" stroke-width="0.6"/>')
        if i % 2 == 0:
            o.append(f'<text x="{X(x):.1f}" y="{Y(0)+14:.1f}" text-anchor="middle" font-size="10">{x}</text>')
    for j in range(0, int(ym // 500) + 1):
        y = j * 500
        o.append(f'<line x1="{X(0):.1f}" y1="{Y(y):.1f}" x2="{X(xm):.1f}" y2="{Y(y):.1f}" stroke="#ddd" stroke-width="0.6"/>')
        o.append(f'<text x="{X(0)-6:.1f}" y="{Y(y)+3:.1f}" text-anchor="end" font-size="10">{y}</text>')
    o.append(f'<rect x="{ml}" y="{mt}" width="{pw}" height="{ph}" fill="none" stroke="#000"/>')
    # 長寬比輔助線
    for ar in (1, 1.5, 2, 3, 4, 5, 7):
        xe = min(xm, ym * ar)
        o.append(f'<line x1="{X(0):.1f}" y1="{Y(0):.1f}" x2="{X(xe):.1f}" y2="{Y(xe/ar):.1f}" stroke="#bbb" stroke-width="0.7"/>')
        o.append(f'<text x="{X(xe)-2:.1f}" y="{Y(xe/ar)-3:.1f}" text-anchor="end" font-size="8" fill="#888">AR {ar:g}</text>')
    # 等值線
    for k in sorted(ch):
        v, e = ch[k]
        seg, last = [], None
        label_done = False
        def flush(seg):
            if len(seg) >= 2:
                pts_ = " ".join(f"{X(a):.1f},{Y(b):.1f}" for a, b, _ in seg)
                dash = ' stroke-dasharray="4 3"' if all(f == 2 for _, _, f in seg) else ""
                o.append(f'<polyline points="{pts_}" fill="none" stroke="#111" stroke-width="1.5"{dash}/>')
        for gi in range(NG):
            d = float(v[gi]); ar = AR0 + DAR * gi
            if d > 0 and np.isfinite(d) and d <= xm * 1.001 and d / ar <= ym * 1.001:
                seg.append((d, d / ar, int(e[gi])))
            else:
                flush(seg); seg = []
        flush(seg)
        for gi in range(NG):          # 標籤:取第一個有效點
            d = float(v[gi]); ar = AR0 + DAR * gi
            if d > 0 and np.isfinite(d) and d <= xm and d / ar <= ym:
                o.append(f'<text x="{X(d)+3:.1f}" y="{Y(d/ar)-3:.1f}" font-size="9" fill="#333">{k:g}</text>')
                break
    o.append(f'<text x="{W/2}" y="{H-8}" text-anchor="middle" font-size="11">板長 Plate Length (mm)</text>')
    o.append(f'<text x="14" y="{mt+ph/2}" text-anchor="middle" font-size="11" transform="rotate(-90 14 {mt+ph/2})">板寬 Plate Width (mm)</text>')
    o.append(f'<text x="{W/2}" y="{H-24}" text-anchor="middle" font-size="9" fill="#555">等值線數字 = NFL (kPa);Pb = 0.008,3 秒;1 kPa ≈ 102 kgf/m²</text>')
    # 讀值點
    inside = L <= xm and S <= ym
    px, py = X(min(L, xm)), Y(min(S, ym))
    o.append(f'<line x1="{px:.1f}" y1="{Y(0):.1f}" x2="{px:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.2"/>')
    o.append(f'<line x1="{px:.1f}" y1="{py:.1f}" x2="{X(xm):.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.2"/>')
    o.append(f'<circle cx="{px:.1f}" cy="{py:.1f}" r="4" fill="#e00"/>')
    o.append(f'<text x="{px+5:.1f}" y="{Y(0)-5:.1f}" font-size="10" fill="#e00">{L:.0f}</text>')
    o.append(f'<text x="{X(xm)-4:.1f}" y="{py-4:.1f}" text-anchor="end" font-size="10" fill="#e00">{S:.0f}</text>')
    # 標註框
    bx, by = ml + 10, mt + 28
    o.append(f'<rect x="{bx}" y="{by}" width="190" height="{44 if item["sub"] else 30}" fill="#fff" stroke="#2a7a2a"/>')
    o.append(f'<text x="{bx+6}" y="{by+14}" font-size="11">NFL = {item["nfltxt"]}</text>')
    if item["sub"]:
        o.append(f'<text x="{bx+6}" y="{by+29}" font-size="10" fill="#555">{_html.escape(item["sub"])}</text>')
    o.append(f'<polyline points="{bx+190},{by+15} {px:.1f},{py:.1f}" fill="none" stroke="#2a7a2a" stroke-width="1.2" marker-end="url(#ar)"/>')
    o.append('<defs><marker id="ar" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#2a7a2a"/></marker></defs>')
    if not inside:
        o.append(f'<text x="{ml+4}" y="{H-24}" font-size="10" fill="#e00">尺寸超出圖框,標示點取圖框邊緣</text>')
    o.append('</svg>')
    return "".join(o)


def svg_defl4(L, S, ts, qi, ws, title):
    """四邊簡支變形圖:δ vs q·(L·S)²(依 Appendix X1 / 線性理論繪製各 AR 曲線),紅線標示本案點。"""
    ar0 = min(L / S, 5.0)
    area = L * S / 1e6
    xp = qi * area ** 2                     # kPa·m⁴ = kN·m²
    xmax = max(xp * 1.6, 1.0)
    xmax = float(np.ceil(xmax / 10) * 10)
    t0 = ts[0]
    W, H, ml, mr, mt, mb = 560, 300, 56, 18, 30, 44
    pw, ph = W - ml - mr, H - mt - mb
    curves = []
    for ar in (1, 2, 3, 4, 5):
        S0 = 1000.0; L0 = ar * S0; a0 = L0 * S0 / 1e6
        pts_ = []
        for i in range(0, 161):
            xx = xmax * i / 160
            pts_.append((xx, deflection4(L0, S0, xx / a0 ** 2, t0)[0] if xx > 0 else 0.0))
        curves.append((ar, pts_))
    S0 = 1000.0; L0 = ar0 * S0; a0 = L0 * S0 / 1e6
    mine = [(xmax * i / 160, deflection4(L0, S0, (xmax * i / 160) / a0 ** 2, t0)[0] if i else 0.0) for i in range(161)]
    ymax = max(max(w for _, w in c[1]) for c in curves + [(0, mine)])
    ymax = max(min(ymax, max(ws) * 1.8), max(ws) * 1.3, 5.0)
    ymax = float(np.ceil(ymax / 5) * 5)
    X = lambda x: ml + x / xmax * pw
    Y = lambda y: mt + ph - min(y, ymax) / ymax * ph
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="100%" style="{_FONT};background:#fff">']
    o.append(f'<text x="{W/2}" y="16" text-anchor="middle" font-size="13" font-weight="bold">{_html.escape(title)}</text>')
    for i in range(0, 6):
        gx = xmax * i / 5
        o.append(f'<line x1="{X(gx):.1f}" y1="{Y(0):.1f}" x2="{X(gx):.1f}" y2="{Y(ymax):.1f}" stroke="#ddd" stroke-width="0.6"/>')
        o.append(f'<text x="{X(gx):.1f}" y="{Y(0)+14:.1f}" text-anchor="middle" font-size="10">{gx:.0f}</text>')
        gy = ymax * i / 5
        o.append(f'<line x1="{X(0):.1f}" y1="{Y(gy):.1f}" x2="{X(xmax):.1f}" y2="{Y(gy):.1f}" stroke="#ddd" stroke-width="0.6"/>')
        o.append(f'<text x="{X(0)-6:.1f}" y="{Y(gy)+3:.1f}" text-anchor="end" font-size="10">{gy:.0f}</text>')
    o.append(f'<rect x="{ml}" y="{mt}" width="{pw}" height="{ph}" fill="none" stroke="#000"/>')
    for ar, c in curves:
        pp = " ".join(f"{X(a):.1f},{Y(b):.1f}" for a, b in c)
        o.append(f'<polyline points="{pp}" fill="none" stroke="#111" stroke-width="1.4"/>')
        a_, b_ = c[-1]
        if b_ <= ymax:
            o.append(f'<text x="{X(a_)-3:.1f}" y="{Y(b_)-3:.1f}" text-anchor="end" font-size="9">AR {ar}</text>')
    pp = " ".join(f"{X(a):.1f},{Y(b):.1f}" for a, b in mine)
    o.append(f'<polyline points="{pp}" fill="none" stroke="#06c" stroke-width="1.6" stroke-dasharray="5 3"/>')
    o.append(f'<text x="{X(0)+6:.1f}" y="{mt+14}" font-size="10" fill="#06c">藍虛線:本案 AR = {L/S:.2f}(t = {t0:.2f} mm)</text>')
    o.append(f'<text x="{W/2}" y="{H-8}" text-anchor="middle" font-size="11">載重 × 面積² Load × Area² (kN·m²) = q × (L·S)²</text>')
    o.append(f'<text x="14" y="{mt+ph/2}" text-anchor="middle" font-size="11" transform="rotate(-90 14 {mt+ph/2})">變形 Deflection (mm)</text>')
    o.append(f'<line x1="{X(xp):.1f}" y1="{Y(0):.1f}" x2="{X(xp):.1f}" y2="{Y(ymax):.1f}" stroke="#e00" stroke-width="2.2"/>')
    for w in sorted(set(round(x, 3) for x in ws)):
        o.append(f'<line x1="{X(0):.1f}" y1="{Y(w):.1f}" x2="{X(xp):.1f}" y2="{Y(w):.1f}" stroke="#e00" stroke-width="2.2"/>')
        o.append(f'<circle cx="{X(xp):.1f}" cy="{Y(w):.1f}" r="3.5" fill="#e00"/>')
        o.append(f'<text x="{X(xp)+6:.1f}" y="{Y(w)-4:.1f}" font-size="11" fill="#e00" stroke="#fff" stroke-width="3" paint-order="stroke">δ = {w:.1f} mm</text>')
    o.append(f'<text x="{X(xp)+4:.1f}" y="{Y(0)-5:.1f}" font-size="10" fill="#e00">{xp:.1f}</text>')
    o.append('</svg>')
    return "".join(o)


def svg_edge(K, span_mm, nfl, title):
    """兩對邊 / 一邊支承:NFL × L² = K(對數直線),標示本案點。"""
    lo, hi = 260.0, 3500.0
    W, H, ml, mr, mt, mb = 560, 300, 56, 18, 30, 44
    pw, ph = W - ml - mr, H - mt - mb
    ylo, yhi = 0.25, 10.0
    X = lambda x: ml + (np.log10(x) - np.log10(lo)) / (np.log10(hi) - np.log10(lo)) * pw
    Y = lambda y: mt + ph - (np.log10(y) - np.log10(ylo)) / (np.log10(yhi) - np.log10(ylo)) * ph
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="100%" style="{_FONT};background:#fff">']
    o.append(f'<text x="{W/2}" y="16" text-anchor="middle" font-size="13" font-weight="bold">{_html.escape(title)}</text>')
    for x in (300, 500, 1000, 2000, 3000):
        o.append(f'<line x1="{X(x):.1f}" y1="{Y(ylo):.1f}" x2="{X(x):.1f}" y2="{Y(yhi):.1f}" stroke="#ddd" stroke-width="0.6"/>')
        o.append(f'<text x="{X(x):.1f}" y="{Y(ylo)+14:.1f}" text-anchor="middle" font-size="10">{x}</text>')
    for y in (0.25, 0.5, 1, 2, 5, 10):
        o.append(f'<line x1="{X(lo):.1f}" y1="{Y(y):.1f}" x2="{X(hi):.1f}" y2="{Y(y):.1f}" stroke="#ddd" stroke-width="0.6"/>')
        o.append(f'<text x="{X(lo)-6:.1f}" y="{Y(y)+3:.1f}" text-anchor="end" font-size="10">{y:g}</text>')
    o.append(f'<rect x="{ml}" y="{mt}" width="{pw}" height="{ph}" fill="none" stroke="#000"/>')
    pts_ = []
    for i in range(61):
        x = 10 ** (np.log10(lo) + (np.log10(hi) - np.log10(lo)) * i / 60)
        y = K / x ** 2
        if ylo <= y <= yhi:
            pts_.append(f"{X(x):.1f},{Y(y):.1f}")
    o.append(f'<polyline points="{" ".join(pts_)}" fill="none" stroke="#111" stroke-width="1.6"/>')
    o.append(f'<text x="{W/2}" y="{H-8}" text-anchor="middle" font-size="11">跨距 / 懸伸長度 (mm)</text>')
    o.append(f'<text x="14" y="{mt+ph/2}" text-anchor="middle" font-size="11" transform="rotate(-90 14 {mt+ph/2})">NFL (kPa)</text>')
    if lo <= span_mm <= hi and ylo <= nfl <= yhi:
        px, py = X(span_mm), Y(nfl)
        o.append(f'<line x1="{px:.1f}" y1="{Y(ylo):.1f}" x2="{px:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.2"/>')
        o.append(f'<line x1="{px:.1f}" y1="{py:.1f}" x2="{X(lo):.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.2"/>')
        o.append(f'<circle cx="{px:.1f}" cy="{py:.1f}" r="4" fill="#e00"/>')
        o.append(f'<text x="{px+6:.1f}" y="{py-6:.1f}" font-size="11" fill="#e00">NFL = {nfl:.2f} kPa</text>')
    else:
        o.append(f'<text x="{ml+8}" y="{mt+16}" font-size="11" fill="#e00">本案點超出圖框(依直線推算 NFL = {nfl:.2f} kPa)</text>')
    o.append('</svg>')
    return "".join(o)


def _img_svg(key, part, marks, texts):
    """原圖(標準 Annex A1 圖影像)疊加紅色標線。part='u' 上圖(NFL)、'l' 下圖(變形)。
    marks: [(px, py)] 影像座標之十字點;texts: [(px, py, 文字)]。回傳 SVG 字串。"""
    d = IMGS[str(key)]
    w, h = d["w"], (d["hu"] if part == "u" else d["hl"])
    src = d["iu"] if part == "u" else d["il"]
    return d, f'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 {w} {h}" width="100%" style="{_FONT};background:#fff;border:1px solid #bbb"><image x="0" y="0" width="{w}" height="{h}" xlink:href="data:image/png;base64,{src}"/>'


def svg_img_nfl(key, L, S, nfltxt, sub):
    d, o = _img_svg(key, "u", None, None)
    x0, sx, yb, sy = d["up"]
    xr = x0 + sx * d["xm"]
    if L > d["xm"] or S > d["tp"]:
        o += (f'<rect x="{x0:.0f}" y="{yb-sy*d["tp"]*0.5-22:.0f}" width="{xr-x0:.0f}" height="44" fill="#fff" fill-opacity="0.9" stroke="#e00"/>'
              f'<text x="{(x0+xr)/2:.0f}" y="{yb-sy*d["tp"]*0.5+6:.0f}" text-anchor="middle" font-size="15" font-weight="bold" fill="#e00">'
              f'尺寸超出圖框(長 {L:.0f} / 短 {S:.0f} mm),無法在此圖上標示讀值點</text>')
        return o + "</svg>"
    px, py = x0 + sx * L, yb - sy * S
    o += f'<line x1="{px:.1f}" y1="{yb:.1f}" x2="{px:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.4"/>'
    o += f'<line x1="{px:.1f}" y1="{py:.1f}" x2="{xr:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.4"/>'
    o += f'<circle cx="{px:.1f}" cy="{py:.1f}" r="4.5" fill="none" stroke="#e00" stroke-width="2"/>'
    ts = 'font-size="13" font-weight="bold" fill="#e00" stroke="#fff" stroke-width="3.5" paint-order="stroke"'
    o += f'<text x="{px+4:.1f}" y="{yb-5:.1f}" {ts}>{L:.0f}</text>'
    o += f'<text x="{xr-4:.1f}" y="{py-5:.1f}" text-anchor="end" {ts}>{S:.0f}</text>'
    tx = min(px + 12, d["w"] - 190)
    ty = py - 26 if py > 90 else py + 30
    o += f'<text x="{tx:.1f}" y="{ty:.1f}" font-size="14" font-weight="bold" fill="#060" stroke="#fff" stroke-width="4" paint-order="stroke">NFL = {_html.escape(nfltxt)}</text>'
    if sub:
        o += f'<text x="{tx:.1f}" y="{ty+16:.1f}" font-size="11" fill="#060" stroke="#fff" stroke-width="3" paint-order="stroke">{_html.escape(sub)}</text>'
    return o + "</svg>"


def svg_img_edge(key, span, nfl, nfltxt, sub):
    """兩對邊 / 單邊支承:ASTM 原圖(A1.27 / A1.28,對數座標)上標示 NFL 與跨距。"""
    d, o = _img_svg(key, "u", None, None)
    ax, bx = d["lx"]; ay, by = d["ly"]
    yl, yh, xl, xh = EDGE_RNG[key]                    # 與計算共用之圖框範圍
    xa, xb = d["xpl"]; yt, yb = d["ytp"], d["ybt"]
    X = lambda v: ax + bx * math.log(v)
    Y = lambda v: ay + by * math.log(v)
    msg = None
    if not (xl <= nfl <= xh):
        msg = f'NFL = {nfl:.2f} kPa 超出橫軸範圍 {xl:g}~{xh:g} kPa,無法在此圖上標示'
    elif not (yl <= span <= yh):
        msg = f'跨距 {span:.0f} mm 超出縱軸範圍 {yl:.0f}~{yh:.0f} mm,無法在此圖上標示'
    if msg:
        o += (f'<rect x="{xa:.0f}" y="{(yt+yb)/2-22:.0f}" width="{xb-xa:.0f}" height="44" fill="#fff" fill-opacity="0.9" stroke="#e00"/>'
              f'<text x="{(xa+xb)/2:.0f}" y="{(yt+yb)/2+6:.0f}" text-anchor="middle" font-size="14" font-weight="bold" fill="#e00">{msg}</text>')
        return o + "</svg>"
    px, py = X(nfl), Y(span)
    o += f'<line x1="{px:.1f}" y1="{yb:.1f}" x2="{px:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.4"/>'
    o += f'<line x1="{px:.1f}" y1="{py:.1f}" x2="{xa:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.4"/>'
    o += f'<circle cx="{px:.1f}" cy="{py:.1f}" r="4.5" fill="none" stroke="#e00" stroke-width="2"/>'
    ts = 'font-size="13" font-weight="bold" fill="#e00" stroke="#fff" stroke-width="3.5" paint-order="stroke"'
    o += f'<text x="{px+4:.1f}" y="{yb-5:.1f}" {ts}>{nfl:.2f}</text>'
    o += f'<text x="{xa+4:.1f}" y="{py-5:.1f}" {ts}>{span:.0f}</text>'
    tx = min(px + 12, d["w"] - 200)
    o += f'<text x="{tx:.1f}" y="{py-26 if py>90 else py+30:.1f}" font-size="14" font-weight="bold" fill="#060" stroke="#fff" stroke-width="4" paint-order="stroke">NFL = {_html.escape(nfltxt)}</text>'
    return o + "</svg>"


def svg_img_defl(key, L, S, qi, ws):
    d, o = _img_svg(key, "l", None, None)
    x0, sx, yb, sy = d["lo"][:4]
    xv = qi * (L * S / 1e6) ** 2                    # kN·m²
    xr = d["xr"]                                    # 繪圖區(圖框)右界 px,逐張量測
    xmax = (xr - x0) / sx                           # 橫軸上限 kN·m²
    ytop = d["lo"][4]
    px = x0 + sx * xv
    ar = max(L, S) / min(L, S)
    msg = None
    if ar > 5.0 + 1e-9:
        msg = f'長寬比 {ar:.2f} > 5,超出本圖曲線範圍(AR=1~5),無法在此圖上標示'
    elif xv > xmax:
        msg = f'q·(L·S)² = {xv:.1f} kN·m² 超出橫軸上限 {xmax:.0f},無法在此圖上標示'
    if msg:
        o += (f'<rect x="{x0:.0f}" y="{(yb+ytop)/2-22:.0f}" width="{xr-x0:.0f}" height="44" fill="#fff" fill-opacity="0.9" stroke="#e00"/>'
              f'<text x="{(x0+xr)/2:.0f}" y="{(yb+ytop)/2+6:.0f}" text-anchor="middle" font-size="15" font-weight="bold" fill="#e00">{msg}</text>')
        return o + "</svg>"
    o += f'<line x1="{px:.1f}" y1="{yb:.1f}" x2="{px:.1f}" y2="{ytop:.1f}" stroke="#e00" stroke-width="2.4"/>'
    o += f'<text x="{px+4:.1f}" y="{yb-5:.1f}" font-size="13" font-weight="bold" fill="#e00" stroke="#fff" stroke-width="3.5" paint-order="stroke">{xv:.1f}</text>'
    for w in sorted(set(round(x, 2) for x in ws)):
        py = yb - sy * w
        if py < ytop:
            o += f'<text x="{x0+8:.1f}" y="{ytop+22:.1f}" font-size="13" fill="#e00">δ = {w:.1f} mm 超出圖框(圖上無法標示)</text>'
            continue
        o += f'<line x1="{x0:.1f}" y1="{py:.1f}" x2="{px:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.4"/>'
        o += f'<circle cx="{px:.1f}" cy="{py:.1f}" r="4.5" fill="none" stroke="#e00" stroke-width="2"/>'
        o += f'<text x="{max(x0+6, px-8):.1f}" y="{py-8:.1f}" text-anchor="{"end" if px > x0 + (xr-x0)*0.6 else "start"}" font-size="14" font-weight="bold" fill="#060" stroke="#fff" stroke-width="4" paint-order="stroke">δ = {w:.1f} mm</text>'
    return o + "</svg>"


def _defl_banner(o, xa, xb, yt, yb, msg):
    return (o + f'<rect x="{xa:.0f}" y="{(yt+yb)/2-22:.0f}" width="{xb-xa:.0f}" height="44" fill="#fff" fill-opacity="0.9" stroke="#e00"/>'
            f'<text x="{(xa+xb)/2:.0f}" y="{(yt+yb)/2+6:.0f}" text-anchor="middle" font-size="14" font-weight="bold" fill="#e00">{msg}</text></svg>')


def svg_img_defl_x(key, Lm, qi, ws, lin):
    """三邊 / 兩對邊 / 一邊支承之標準變形圖(下圖),橫軸 q·L⁴ (kN·m²),縱軸 δ (mm)。
    lin=True:線性座標(三邊,key='3_xx');lin=False:對數座標(兩對邊 E2 / 一邊 E1)。"""
    d, o = _img_svg(key, "l", None, None)
    xv = qi * (Lm / 1000.0) ** 4
    if lin:
        x0, sx, yb, sy, yt = d["lo"]
        xr = d["xr"]
        X = lambda v: x0 + sx * v
        Y = lambda v: yb - sy * v
        xmax, ymax = d["xmax_l"], d["ymax_l"]; xmin = 0.0; ymin = 0.0
        xa = x0
    else:
        ax_, bx_ = d["llx"]; ay_, by_ = d["lly"]
        xa, xr = d["lxpl"]; yt, yb = d["lyt"], d["lyb"]
        X = lambda v: ax_ + bx_ * math.log(v)
        Y = lambda v: ay_ + by_ * math.log(v)
        xmin, xmax = d["lxlim"]; ymin, ymax = d["lylim"]
    if xv > xmax or xv < xmin:
        return _defl_banner(o, xa, xr, yt, yb, f'q·L⁴ = {xv:.3g} kN·m² 超出橫軸範圍({xmin:.3g}~{xmax:.3g}),無法在此圖上標示')
    px = X(xv)
    o += f'<line x1="{px:.1f}" y1="{yb:.1f}" x2="{px:.1f}" y2="{yt:.1f}" stroke="#e00" stroke-width="2.4"/>'
    o += f'<text x="{px+4:.1f}" y="{yb-5:.1f}" font-size="13" font-weight="bold" fill="#e00" stroke="#fff" stroke-width="3.5" paint-order="stroke">{xv:.3g}</text>'
    for w in sorted(set(round(x, 2) for x in ws)):
        if w > ymax or w < ymin:
            o += f'<text x="{xa+8:.1f}" y="{yt+22:.1f}" font-size="13" fill="#e00">δ = {w:.1f} mm 超出圖框(圖上無法標示)</text>'
            continue
        py = Y(w)
        o += f'<line x1="{xa:.1f}" y1="{py:.1f}" x2="{px:.1f}" y2="{py:.1f}" stroke="#e00" stroke-width="2.4"/>'
        o += f'<circle cx="{px:.1f}" cy="{py:.1f}" r="4.5" fill="none" stroke="#e00" stroke-width="2"/>'
        o += (f'<text x="{max(xa+6, px-8):.1f}" y="{py-8:.1f}" text-anchor="{"end" if px > xa + (xr-xa)*0.6 else "start"}" font-size="14" font-weight="bold" fill="#060" '
              f'stroke="#fff" stroke-width="4" paint-order="stroke">δ = {w:.1f} mm</text>')
    return o + "</svg>"


def _k3(lt):
    return f"3_{int(lt['D'])}" if lt["kind"] == "mono" else f"3L_{lt['ck']}"


def _ke(lt, mi):
    return ("E2" if mi == 2 else "E1") + ("" if lt["kind"] == "mono" else "L")


def build_report():
    esc = _html.escape
    out = ['<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><title>ASTM E1300-16 玻璃檢核計算報表</title>',
           '<style>body{%s;max-width:900px;margin:20px auto;color:#111;font-size:13px}h1{font-size:20px;margin:0}h2{font-size:15px;border-bottom:2px solid #333;'
           'padding-bottom:3px;margin-top:22px}table{border-collapse:collapse;width:100%%;margin:6px 0;font-size:12px}th,td{border:1px solid #999;padding:3px 6px;text-align:center}'
           'th{background:#eee}.fig{page-break-inside:avoid;margin:10px 0}.note{color:#555;font-size:11px}.warn{color:#a30;font-size:12px}.box{border:1px solid #999;padding:6px 10px;margin:6px 0}'
           '.wm{position:fixed;left:50%%;top:55%%;width:640px;height:640px;margin:-320px 0 0 -320px;'
           'background:url(data:image/png;base64,@@WM@@) center/contain no-repeat;opacity:.11;z-index:-1;'
           '-webkit-print-color-adjust:exact;print-color-adjust:exact}'
           '.fig svg,svg{mix-blend-mode:multiply}.firm{font-size:17px;font-weight:600;margin-top:2px}.firm-en{font-size:12px;color:#444;margin-bottom:4px}'
           '@media print{body{margin:0}}</style></head><body><div class="wm"></div>' % _FONT]
    out[1] = out[1].replace('@@WM@@', WM_B64)
    out.append("<h1>ASTM E1300-16 玻璃檢核計算報表</h1>")
    out.append("<div class='firm'>賴映宇結構技師事務所</div><div class='firm-en'>YYLai Structural Engineer &amp; Associates</div>")
    if proj_name or proj_item:
        out.append(f"<div class='box'>專案:{esc(proj_name)}　　玻璃編號 / 位置:{esc(proj_item)}</div>")
    out.append("<h2>1. 設計條件</h2><table>")
    out.append(f"<tr><th>支承條件</th><td>{esc(mode)}</td><th>尺寸</th><td>{esc(geom)}</td></tr>")
    out.append(f"<tr><th>設計風壓</th><td>{q_kgf:,.0f} kgf/m² ({q_kpa:.2f} kPa)</td><th>載重期間</th><td>{esc(dur)}</td></tr>")
    out.append(f"<tr><th>組成</th><td colspan=3>{esc(' / '.join(x['name'] + ':' + x['spec'] for x in lites))}"
               + (f"(LSF 短期 = {', '.join(f'{x:.3f}' for x in lsf_s)})" if ig else "") + "</td></tr></table>")
    out.append("<h2>2. 強度檢核:查表法(LR = NFL × GTF ÷ LSF)</h2>")
    out.append(pd.DataFrame(rowsA).to_html(index=False, border=0, escape=True))
    if ovA:
        out.append(f"<div class='box'><b>{esc(str(ovA[0]))}:{esc(str(ovA[1]))}</b>　{esc(str(ovA[2]))}</div>")
    for n in notes_all:
        out.append(f"<div class='warn'>※ {esc(n)}</div>")
    out.append("<h2>3. ASTM E1300-16 Annex A1 非因子化載重圖(NFL)與讀值</h2>")
    out.append("<div class='note'>下圖為 ASTM E1300-16 Annex A1 原圖(局部引用,僅供個人工程計算書附圖),紅線為本案尺寸讀值,綠字為本工具查得之 NFL;"
               "可目視確認紅點落在標準圖上之等值線位置。</div>")
    for i, lt in enumerate(lites):
        ra = repA[i]
        out.append(f"<div class='fig'><b>{esc(lt['name'])}:{esc(lt['spec'])}</b>")
        if ra is None:
            _why = ";".join(lite_notes[i]) or "不適用本圖表"
            out.append(f"<div class='warn'>此片無法依圖表判定:{esc(_why)}。下圖僅附對應 ASTM 原圖供覆核,不標示讀值點。</div>")
            _nk = (str(lt["ck"]) if mi == 0 else _k3(lt) if mi == 1 else _ke(lt, mi))
            if _nk in IMGS and "iu" in IMGS[_nk]:
                out.append(_img_svg(_nk, "u", None, None)[1] + "</svg>")
            else:
                out.append("<div class='note'>此條件無對應之 ASTM 原圖。</div>")
            out.append("</div>")
            continue
        nfl_kpa = ra["nfl"]
        if ra["bound"] == "lo":
            nt, sub = f"< {ra['bd'][1]:.2f} kPa (< {ra['bd'][1]*KPA_TO_KGF:,.0f} kgf/m²)", "低於最低等值線(單側界限)"
        elif ra["bound"] == "hi":
            nt, sub = f"> {ra['bd'][1]:.2f} kPa (> {ra['bd'][1]*KPA_TO_KGF:,.0f} kgf/m²)", "高於最高等值線(單側界限)"
        else:
            nt = f"{nfl_kpa:.2f} kPa ({nfl_kpa*KPA_TO_KGF:,.0f} kgf/m²)"
            sub = "估算值(非正式查表值)" if ra["est"] else ""
        item = dict(nfltxt=nt, sub=sub)
        if mi == 0 and str(lt["ck"]) in IMGS:
            out.append(svg_img_nfl(lt["ck"], L, S, nt, sub))
        elif mi == 0 and lt["ck"] in X4_MAX:
            ttl = (f"{lt['spec']} — 四邊簡支 NFL 圖(Fig. A1.{ 'x' })" if False else f"{lt['spec']} — 四邊簡支 非因子化載重圖 NFL (kPa)")
            out.append(svg_nfl4(item, lt["ck"], L, S, ttl))
        elif mi == 1 and _k3(lt) in IMGS:
            out.append(svg_img_nfl(_k3(lt), dimB, dimA, nt, sub))
        elif mi in (2, 3) and _ke(lt, mi) in IMGS:
            out.append(svg_img_edge(_ke(lt, mi), dimA, nfl_kpa, nt, sub))
        elif mi in (2, 3) and int(lt["D"]) in ((K2 if mi == 2 else K1) if lt["kind"] == "mono" else (K2LG if mi == 2 else K1LG)):
            tab = (K2 if mi == 2 else K1) if lt["kind"] == "mono" else (K2LG if mi == 2 else K1LG)
            out.append(svg_edge(tab[int(lt["D"])], dimA, nfl_kpa, f"{lt['spec']} — " + ("兩對邊支承" if mi == 2 else "一邊支承(懸臂)") + " NFL(對數座標)"))
        else:
            out.append("<div class='note'>此支承條件之 NFL 圖尚未繪製於報表,數值見上表。</div>")
        gt = ra
        if ra["bound"] in ("lo", "hi"):
            lo_ = ra["bound"] == "lo"; sg = "<" if lo_ else ">"; sg2 = ">" if lo_ else "<"
            bl = ra["blr"]
            out.append(f"<div class='box'>NFL {sg} {ra['bd'][1]:.2f} kPa(單側界限,不採外插值);LR = NFL × GTF ÷ LSF {sg} {ra['bd'][1]:.2f} × {gt['gv']:.2f} ÷ {gt['lv']:.3f}"
                       f" = {bl:.2f} kPa = {bl*KPA_TO_KGF:,.0f} kgf/m²(工況:{esc(gt['cn'])});設計風壓 {q_kpa:.2f} kPa,D/C {sg2} {q_kpa/bl:.2f}</div></div>")
        elif ra["est"]:
            out.append(f"<div class='box'>估算值(非正式查表值):LR ≈ {nfl_kpa:.2f} × {gt['gv']:.2f} ÷ {gt['lv']:.3f} = {gt['lr']:.2f} kPa"
                       f" = {gt['lr']*KPA_TO_KGF:,.0f} kgf/m²(工況:{esc(gt['cn'])});未作合格判定</div></div>")
        else:
            out.append(f"<div class='box'>LR = NFL × GTF ÷ LSF = {nfl_kpa:.2f} × {gt['gv']:.2f} ÷ {gt['lv']:.3f} = {gt['lr']:.2f} kPa"
                       f" = {gt['lr']*KPA_TO_KGF:,.0f} kgf/m²(工況:{esc(gt['cn'])});設計風壓 {q_kpa:.2f} kPa,D/C = {q_kpa/gt['lr']:.2f}</div></div>")
    out.append("<h2>4. 變形檢核</h2>")
    _dfD = pd.DataFrame(rowsD).drop(columns=["公式解:線性板理論", "X1 近似公式(Appendix X1)", "公式解:線性理論", "規範變形圖"], errors="ignore")
    out.append(_dfD.to_html(index=False, border=0, escape=True))
    out.append("<ul>" + "".join(f"<li>{esc(t)}</li>" for t in defl_txt) + "</ul>")
    if mi == 0:
        for i, lt in enumerate(lites):
            rd_ = repD[i]
            ttl = f"{lt['spec']} — 變形圖 δ vs q·(L·S)²(分擔風壓 {rd_['qi']:.2f} kPa)"
            if str(lt["ck"]) in IMGS:
                out.append(f"<div class='fig'><b>{esc(lt['name'])}:{esc(lt['spec'])} — 標準變形圖,分擔風壓 {rd_['qi']:.2f} kPa</b>"
                           + svg_img_defl(lt["ck"], L, S, rd_["qi"], rd_["ws"]) + "</div>")
            else:
                out.append("<div class='fig'>" + svg_defl4(L, S, rd_["ts"], rd_["qi"], rd_["ws"], ttl) + "</div>")
        _lgc = [u for u, lt in zip(chart_used, lites) if lt["kind"] == "lg"]
        _txt = "標準變形圖上之紅點:單片玻璃為本工具以 Appendix X1 / 線性理論算得之變形(不是由圖上讀出),應落在對應 AR 曲線附近;"
        if _lgc and all(_lgc):
            _txt += "LG 之紅點為由標準 LG 圖(AR=1~5 曲線數位化,依 AR 以 ln δ–ln AR 內插)查得之近似值,圖為 50°C 結果;AR1~AR3 曲線重疊/交叉處數位化不確定度約 1~3 mm。"
        elif _lgc:
            _txt += "LG 若超出標準圖框(AR>5、橫軸或 δ 超出)則改以兩條水平紅線表示兩種剛度假設(代號最小厚度 / 分層)的估算結果,供與標準 LG 曲線對照,不代表標準 LG 圖的上下界。"
        out.append("<div class='note'>" + _txt + "</div>")
    elif mi in (1, 2, 3):
        _lm = dimA                                     # 三邊:自由邊 F;兩對邊:跨距 L;一邊:懸伸 L
        for i, lt in enumerate(lites):
            rd_ = repD[i]
            _k = _k3(lt) if mi == 1 else _ke(lt, mi)
            if _k in IMGS and "il" in IMGS[_k]:
                out.append(f"<div class='fig'><b>{esc(lt['name'])}:{esc(lt['spec'])} — 標準變形圖(橫軸 q·L⁴,L = {'自由邊長度' if mi == 1 else ('兩支承邊間跨距' if mi == 2 else '懸伸長度')}),分擔風壓 {rd_['qi']:.2f} kPa</b>"
                           + svg_img_defl_x(_k, _lm, rd_["qi"], rd_["ws"], mi == 1) + "</div>")
        if mi == 1 and all(chart_used):
            out.append("<div class='note'>三邊標準變形圖上之紅點為由 AR 線(P/F 內插)讀得之近似值(圖上直線數位化,誤差約 0.3 mm 內);"
                       "圖上 AR>1.5 之線適用於 P/F ≥ 1.5。</div>")
        elif mi in (2, 3) and all(u for u, lt in zip(chart_used, lites) if lt["kind"] == "lg") and any(lt["kind"] == "lg" for lt in lites):
            out.append("<div class='note'>標準變形圖上之紅點:LG 為由標準圖直線(依代號厚度)讀得之近似值(圖為 50°C 結果,數位化誤差約 2% 內);單片為梁 / 懸臂公式之變形,應落在對應厚度直線上。</div>")
        else:
            out.append("<div class='note'>標準變形圖上之紅點為本工具以線性理論 / 梁公式算得之變形(不是由圖上讀出),應落在對應曲線附近"
                       + ("(三邊圖以 AR 區分曲線;超出圖框者以線性理論估算)" if mi == 1 else "(曲線依玻璃厚度區分,膠合玻璃以代號厚度對照)") + "。</div>")
    if si_rows:
        out.append("<h2>5. 結構矽膠受力寬度</h2>")
        out.append(pd.DataFrame(si_rows).to_html(index=False, border=0, escape=True))
        out.append("<div class='note'>20 / 30 psi 為使用者設定之設計強度,非 ASTM 數值。</div>")
    out.append("<h2>說明與限制</h2><div class='note'>本報表依 ASTM E1300-16 查圖表法(NFL × GTF ÷ LSF);圖表為影像數位化,結果與標準原圖讀值可能有數個百分點差異。"
               "LG 變形以標準圖數位化曲線查得近似值(超出圖框時為估算範圍)。ASTM E1300 不規定變形限值。請與標準原文及專案軟體覆核後方可送審。</div>")
    out.append("</body></html>")
    return "".join(out)


st.divider()
try:
    _rep_html = build_report()
    st.download_button("📄 下載計算報表(HTML,可用瀏覽器列印成 PDF)", data=_rep_html.encode("utf-8"),
                       file_name="ASTM_E1300_計算報表.html", mime="text/html")
    with st.expander("預覽報表"):
        try:
            import streamlit.components.v1 as _cv
            _cv.html(_rep_html, height=900, scrolling=True)
        except Exception:
            st.caption("此環境無法內嵌預覽,請下載後開啟。")
except Exception as _e:
    st.warning(f"報表產生失敗:{_e}")
